async function loadFromDisk(opts = {}) { try { const resp = await fetch("/api/state", { cache: "no-store" }); if (resp.status === 404) { if (!opts.silent) showToast("磁盘尚无保存文件"); return false; } const data = await resp.json().catch(() => ({})); if (!resp.ok || data.ok !== true) { if (!opts.silent) showToast(`从磁盘加载失败：${data.error || resp.status}`); return false; } const parsed = data.state; if (!parsed || !Array.isArray(parsed.canvases) || !parsed.canvases.length) { if (!opts.silent) showToast("磁盘文件里没有有效画布"); return false; } if (!opts.silent && !window.confirm("从磁盘加载将覆盖当前所有画布，是否继续？")) return false; if (opts.silent && (isDirty || autosaveTimer || editing || drag || resizing || pan || userTouched)) return false; commitPendingEdit(); if (!opts.silent) pushHistory(); state = normalizeState(parsed); clearTransient(); if (opts.silent) { history = []; future = []; } render(); saveLocal("已从磁盘加载"); if (!opts.silent) showToast("已从磁盘加载"); return true; } catch (err) { if (!opts.silent) showToast(`从磁盘加载失败：${err.message || err}`); return false; } }
